def insert(intervals, newInterval):
    result = []
    for i, (s, e) in enumerate(intervals):
        if newInterval[1] < s:
            result.append(newInterval)
            return result + intervals[i:]
        elif newInterval[0] > e:
            result.append([s, e])
        else:
            newInterval = [min(s, newInterval[0]), max(e, newInterval[1])]
    result.append(newInterval)
    return result

